mapper.select:
SELECT * FROM (SELECT * FROM SMT_AUTH_IDENTITY_ALIAS WHERE PARK_ID = #{scope.parkId}
  AND ACCESS_TYPE = #{scope.accessType} AND DEVICE_ID = #{scope.deviceId}
  AND RESOURCE_TYPE = #{scope.resourceType} AND RESOURCE_VALUE = #{scope.resourceId}
  AND SERVICE_TYPE = #{scope.serviceType} AND CREDENTIAL_CHANNEL = #{scope.credentialChannel}
  AND SUBJECT_TYPE = #{scope.subjectType} AND ALIAS_KIND = #{kind} AND ALIAS_VALUE = #{value}
  ORDER BY SUBJECT_ID, RESOURCE_GENERATION DESC) WHERE ROWNUM <= 201
